<template><div class="address-edit"><el-form :model="form" label-position="top"><el-form-item label="收货人"><el-input v-model="form.name" placeholder="请输入收货人姓名"/></el-form-item><el-form-item label="手机号"><el-input v-model="form.phone" placeholder="请输入手机号"/></el-form-item><el-form-item label="所在地区"><el-input v-model="form.region" placeholder="省/市/区"/></el-form-item><el-form-item label="详细地址"><el-input v-model="form.detail" type="textarea" :rows="3" placeholder="请输入详细地址"/></el-form-item><el-form-item label="设为默认"><el-switch v-model="form.is_default"/></el-form-item></el-form><div class="footer"><el-button type="primary" @click="save" style="width:100%">保存</el-button></div></div></template><script setup>import{reactive,onMounted}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import request from'@/utils/request';const route=useRoute();const router=useRouter();const form=reactive({id:null,name:'',phone:'',region:'',detail:'',is_default:0});const save=async()=>{if(form.id){await request({url:`/addresses/${form.id}`,method:'put',data:form})}else{await request({url:'/addresses',method:'post',data:form})}ElMessage.success('保存成功');router.back()};onMounted(()=>{if(route.query.id){Object.assign(form,JSON.parse(route.query.data||'{}'))}})</script><style scoped>.address-edit{padding:20px}.footer{position:fixed;bottom:0;left:0;right:0;padding:15px 20px;background:#fff;border-top:1px solid #eee}</style>
